// NAIVE: works locally, breaks the instant you scale past one instance
const sessions = new Map();

function login(userId, res) {
  const token = ids.next();
  sessions.set(token, { userId });   // lives only in THIS process's memory
  res.cookie('session', token);
}

async function login(userId, res) {
  const token = ids.next();
  await redis.set(`session:${token}`, JSON.stringify({ userId }), { EX: 3600 });
  res.cookie('session', token);
}

async function currentUser(token) {
  const raw = await redis.get(`session:${token}`);
  return raw ? JSON.parse(raw).userId : null;
}

// scale up: spin up N more identical containers, register with the LB
// scale down: stop accepting new connections, let in-flight ones finish
// either way: zero coordination between instances required

async function onStartup(instanceId, address) {
  await registry.register(instanceId, address, { ttl: 15 });

  setInterval(() => registry.renew(instanceId, { ttl: 15 }), 5000);
}

async function callDownstream(serviceName, req) {
  const instances = await registry.healthyInstances(serviceName);
  const target = instances[Math.floor(Math.random() * instances.length)];
  return http.request(target.address, req);
}
